    [3079]={name="Skorn's Rifle",quality=2,ilvl=12,reqLevel=6,sourceType="quest_reward",instructions="Reward from the quest 'The Demon Scarred Cloak'. Pick it over the other reward choices. The quest is in Mulgore. Objective: Find someone who knows of Ghost Howl. Provided item:.",zone="Mulgore",questName="The Demon Scarred Cloak",lore="The ragged hide of Ghost Howl still bears a terrible wound, gained from the wolf's battles against the Burning Legion. Perhaps someone in Bloodhoof Village should know of Ghost Howl's demise...."},
    [3152]={name="Driving Gloves",quality=1,ilvl=9,reqLevel=7,sourceType="quest_reward",instructions="Reward from the quest 'Operation Recombobulation'. Pick it over the other reward choices. Starts with Razzle Sprysprocket in Dun Morogh. Objective: Bring Razzle Sprysprocket in Kharanos 8 Restabilization Cogs and 8 Gyromechanic Gears.",zone="Dun Morogh",questName="Operation Recombobulation",lore="Upon further analysis of the Gnomeregan situation, it would appear as though we not only failed to eradicate the troggs but we also happened to turn most of the gnomish race into horrific, mindless, evil-doing leper gnomes."},
    [3158]={name="Burnt Hide Bracers",quality=1,ilvl=12,reqLevel=10,sourceType="quest_reward",instructions="Reward from the quest 'Rat Catching'. Pick it over the other reward choices. Starts with Mountaineer Kadrell in Loch Modan. Objective: Bring 12 Tunnel Rat Ears to Mountaineer Kadrell in Thelsamar.",zone="Loch Modan",questName="Rat Catching",lore="We have a real infestation problem to the west. Tunnel rat kobolds have moved into the foothills, setting up dens and fouling our land with their filth!"},
    [3161]={name="Robe of the Keeper",quality=2,ilvl=15,reqLevel=9,sourceType="quest_reward",instructions="Reward from the quest 'Filthy Paws'. Pick it over the other reward choices.",zone="Loch Modan",questName="Filthy Paws",lore="The Silver Stream Mine to the east ran dry long ago. It was converted by the Miners' League into a storage depot, but now Kobolds have moved in, putting their filthy paws on good, Dwarven tools!"},
    [3184]={name="Hook Dagger",quality=2,ilvl=20,reqLevel=15,sourceType="world_drop",instructions="World drop around level 15-21.",zone="The Barrens",zoneOpen=true},
    [3186]={name="Viking Sword",quality=2,ilvl=30,reqLevel=25,sourceType="world_drop",instructions="World drop around level 25-31."},
    [3187]={name="Sacrificial Kris",quality=2,ilvl=44,reqLevel=39,sourceType="world_drop",instructions="World drop around level 38-45.",zone="Stranglethorn Vale"},
