    [12040]={name="Forest Pendant",quality=2,ilvl=38,reqLevel=33,sourceType="world_drop",instructions="World drop around level 33-39.",zone="Stranglethorn Vale"},
    [12041]={name="Windshear Leggings",quality=2,ilvl=54,reqLevel=48,sourceType="quest_reward",instructions="Reward from the quest 'Abandoned Hope'. Pick it over the other reward choices. Starts with Marshal Windsor in Burning Steppes. Objective: Give Marshal Maxwell the bad news.",zone="Blackrock Depths",questName="Abandoned Hope",lore="Bolvar is a fool. I was gathering his precious 'proof' so that I could shove it down his throat. He is a blind buffoon. Proof stands two feet away from him and he does not see."},
    [12047]={name="Spectral Necklace",quality=2,ilvl=30,reqLevel=25,sourceType="world_drop",instructions="World drop around level 25-31.",zone="Stranglethorn Vale"},
    [12052]={name="Ring of the Moon",quality=2,ilvl=21,reqLevel=16,sourceType="world_drop",instructions="World drop around level 16-22.",zone="The Barrens",zoneOpen=true},
    [12053]={name="Volcanic Rock Ring",quality=2,ilvl=21,reqLevel=16,sourceType="world_drop",instructions="World drop around level 16-22.",zone="The Barrens",zoneOpen=true},
    [12054]={name="Demon Band",quality=2,ilvl=24,reqLevel=19,sourceType="world_drop",instructions="World drop around level 19-26.",zone="The Barrens",zoneOpen=true},
    [12061]={name="Blade of Reckoning",quality=2,ilvl=60,reqLevel=50,sourceType="quest_reward",instructions="Reward from the quest 'Jail Break!'. Pick it over the other reward choices. Starts with Marshal Windsor in Burning Steppes. Objective: Help Marshal Windsor get his gear back and free his friends. Return to Marshal Maxwell if you succeed.",zone="Blackrock Depths",questName="Jail Break!",lore="We need to get out of here. Help me get my gear back from the supply area and free my friends. If we make it out of here, you are to proceed to Morgan's Vigil and speak with Marshal Maxwell."},
    [12062]={name="Skilled Fighting Blade",quality=2,ilvl=60,reqLevel=50,sourceType="quest_reward",instructions="Reward from the quest 'Jail Break!'. Pick it over the other reward choices. Starts with Marshal Windsor in Burning Steppes. Objective: Help Marshal Windsor get his gear back and free his friends. Return to Marshal Maxwell if you succeed.",zone="Blackrock Depths",questName="Jail Break!",lore="We need to get out of here. Help me get my gear back from the supply area and free my friends. If we make it out of here, you are to proceed to Morgan's Vigil and speak with Marshal Maxwell."},
    [12066]={name="Shaleskin Cape",quality=2,ilvl=58,reqLevel=52,sourceType="quest_reward",instructions="Reward from the quest 'A Taste of Flame'. Pick it over the other reward choices. Starts with Cyrus Therepentous in Burning Steppes. Objective: Travel to Blackrock Depths and slay Bael'Gar.You only know that the giant resides inside Blackrock Depths. Remember to use the Altered Black Dragonflight Molt on Bael'Gar's remains to capture the Fiery Essence.Return the Encased Fiery Essence to Cyrus Therepentous.",zone="Blackrock Depths",questName="A Taste of Flame",lore="I wish to taste the searing flames of the mountain of fire. To let the molten fires of Blackrock cascade across my being. That essence, that searing heat, it is what I crave."},
    [12114]={name="Nightfall Gloves",quality=2,ilvl=56,reqLevel=48,sourceType="quest_reward",instructions="Reward from the quest 'Disharmony of Fire'. Pick it over the other reward choices. Starts with Thunderheart in Blackrock Depths. Objective: Enter Blackrock Depths and track down Lord Incendius. Slay him and return any source of information you may find to Thunderheart.",zone="Blackrock Depths",questName="Disharmony of Fire",lore="I can taste the foulness in the air that surrounds you. There is another, hidden in the depths of Blackrock, who does control this foulness."},
    [12247]={name="Broad Bladed Knife",quality=2,ilvl=32,reqLevel=27,sourceType="vendor",instructions="Bought from Ott.",zone="Hillsbrad Foothills",npc="Ott"},
    [12248]={name="Daring Dirk",quality=2,ilvl=34,reqLevel=29,sourceType="vendor",instructions="Bought from Lhara.",zone="Goldshire",npc="Lhara"},
