    [12470]={name="Sandstalker Ankleguards",quality=3,ilvl=47,reqLevel=42,sourceType="boss_drop",instructions="Drops from Zerillis.",zone="Zul'Farrak",npc="Zerillis"},
    [12522]={name="Bingles' Flying Gloves",quality=2,ilvl=15,reqLevel=12,sourceType="quest_reward",instructions="Reward from the quest 'Bingles' Missing Supplies'. Starts with Bingles Blastenheimer in Loch Modan. Objective: Find and return Bingles' supplies:Bingles' Wrench, Bingles' Screwdriver, Bingles' Hammer, and Bingles' Blastencapper.",zone="Loch Modan",questName="Bingles' Missing Supplies",lore="As if crashing into the Loch wasn't bad enough, troggs from the nearby island attacked me and stole my tools and special Blastenheimer Blastencapper explosives."},
    [12777]={name="Blazing Rapier",quality=3,ilvl=56,reqLevel=51,sourceType="profession",instructions="Crafted with Blacksmithing (requires skill 1).",profession="Blacksmithing"},
    [12781]={name="Serenity",quality=3,ilvl=57,reqLevel=52,sourceType="profession",instructions="Crafted with Blacksmithing (requires skill 1).",profession="Blacksmithing"},
